def investigate(context, acquire):
    events = context.get('events')
    if events is None:
        events = []
    count = 0
    status = 'open'
    pending = []
    for event in events:
        op = event.get('op')
        if op == 'feed':
            if status == 'error' or status == 'finished':
                continue
            data = event.get('bytes')
            if data is None:
                data = []
            pending.extend(data)
            text = None
            while len(pending) > 0:
                lead = pending[0]
                if lead < 128:
                    need = 0
                elif 192 <= lead <= 223:
                    need = 1
                elif 224 <= lead <= 239:
                    need = 2
                elif 240 <= lead <= 247:
                    need = 3
                else:
                    status = 'error'
                    pending = []
                    break
                if len(pending) < 1 + need:
                    break
                valid = True
                index = 1
                while index <= need:
                    trail = pending[index]
                    if trail < 128 or 191 < trail:
                        valid = False
                        break
                    index = index + 1
                if not valid:
                    status = 'error'
                    pending = []
                    break
                if need == 0:
                    low = 0
                    high = 127
                elif need == 1:
                    low = 128
                    high = 2047
                elif need == 2:
                    low = 2048
                    high = 65535
                else:
                    low = 65536
                    high = 1114111
                value = lead & (127 >> need)
                index = 1
                while index <= need:
                    value = (value << 6) | (pending[index] & 63)
                    index = index + 1
                if value < low or value > high or (55296 <= value <= 57343):
                    status = 'error'
                    pending = []
                    break
                text = ''.join(chr(item) for item in pending[:1 + need])
                del pending[:1 + need]
            if status == 'error':
                continue
            if text is not None:
                count = count + len(text)
        elif op == 'finish':
            if status == 'error' or status == 'finished':
                continue
            if len(pending) > 0:
                status = 'error'
                pending = []
            else:
                status = 'finished'
        elif op == 'reset':
            count = 0
            status = 'open'
            pending = []
    return {'count': count, 'status': status}

